s+="""
test('webhook validates the url and builds a JSON POST payload', async () => {
  const log = [];
  const notifier = createNotifier('webhook', {
    transport: transportWithLog(log),
    throttleStore: new Map(),
    now: () => new Date('2026-01-02T03:04:05.000Z')
  });

  for (const webhookUrl of [undefined, 'http://hooks.example.com/x']) {
    await assert.rejects(
      () => notifier.send({ id: 'bad', webhookUrl }, { title: 'T', body: 'B' }),
      err => err instanceof TypeError && /webhookUrl/.test(err.message)
    );
  }

  const user = { id: 'u5', name: 'Eli', webhookUrl: 'https://hooks.example.com/u5' };
  const result = await notifier.send(user, { title: 'Hi {{name}}', body: 'A {{category}} note' });

  assert.equal(result.status, 'sent');
  assert.equal(result.channel, 'webhook');
  assert.equal(log[0].channel, 'webhook');
  assert.equal(log[0].url, 'https://hooks.example.com/u5');
  assert.equal(log[0].method, 'POST');
  assert.deepEqual(log[0].headers, { 'content-type': 'application/json' });
  assert.equal(log[0].title, 'Hi Eli');
  assert.equal(log[0].metadata.category, 'general');
  assert.equal(
    log[0].json,
    JSON.stringify({ title: 'Hi Eli', body: 'A general note', category: 'general', userId: 'u5' })
  );
});

test('webhook defaults to 10 per hour, honors maxPerHour, and requires a transport', async () => {
  const user = { id: 'u5', webhookUrl: 'https://hooks.example.com/u5' };
  const message = { title: 'One', body: 'Two', category: 'release' };
  const now = () => new Date('2026-01-02T03:04:05.000Z');

  const defaulted = createNotifier('webhook', { transport: transportWithLog([]), throttleStore: new Map(), now });
  assert.equal(defaulted.maxPerHour, 10);
  for (let i = 0; i < 10; i++) {
    assert.equal((await defaulted.send(user, message)).status, 'sent');
  }
  const eleventh = await defaulted.send(user, message);
  assert.equal(eleventh.status, 'throttled');
  assert.match(eleventh.reason, /webhook hourly limit/);

  const limited = createNotifier('webhook', {
    transport: transportWithLog([]),
    throttleStore: new Map(),
    maxPerHour: 1,
    now
  });
  assert.equal((await limited.send(user, message)).status, 'sent');
  assert.equal((await limited.send(user, message)).status, 'throttled');

  const unconfigured = createNotifier('webhook', { throttleStore: new Map() });
  await assert.rejects(
    () => unconfigured.send(user, message),
    err => err.constructor === Error && err.message === 'webhook transport is not configured'
  );
});
"""
